#include <stm32f10x.h>
#include "GPIO.h"
#include "Delay.h"
#include "OLED.h"

int main(void)
{
    MyGPIO_Init();
    OLED_Init();
    OLED_ShowString(1, 1, "Hello, World!");
    while (1)
    {
        GPIO_ResetBits(GPIOC, GPIO_Pin_13);
        Delay_ms(1000);
        GPIO_SetBits(GPIOC, GPIO_Pin_13);
        Delay_ms(1000);
    }
}
